-- LOCAL DEVELOPMENT ONLY. Gives the Core API's restricted role a well-known password on the local server.
-- On Supabase, the password is generated by scripts/provision-db-credentials.mjs and never committed.
alter role midan_api login password 'midan-api-local';
-- The local development sign-up code, so the database gate behaves as it does hosted. Its plain value
-- is "local-dev-access" and appears in .env.local.example; never reuse it anywhere else.
insert into private.signup_access (code_hash, note)
select encode(sha256(convert_to('local-dev-access', 'UTF8')), 'hex'), 'Local development server'
where not exists (
  select 1 from private.signup_access where code_hash = encode(sha256(convert_to('local-dev-access', 'UTF8')), 'hex')
);
-- The importer, which can only call the import functions (see scripts/import-data.mjs).
alter role midan_importer login password 'midan-importer-local';
-- The AI service's checkpoint login (LangGraph state only).
alter role midan_ai login password 'midan-ai-local';
